contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        require(c.pot() == 0);
        uint balBefore = address(c).balance;
        c.play{value: amount}();
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;
        // Either the round did not trigger a payout: pot grew by 10 and the
        // contract holds exactly its previous balance plus the ticket, or the
        // round paid out: pot reset to 0 and the contract holds exactly its
        // previous balance (the 10 wei were fully distributed).
        assert(
            (potAfter == 10 && balAfter == balBefore + 10)
            ||
            (potAfter == 0 && balAfter == balBefore)
        );
    }
    receive() external payable {}
}

